#!/usr/bin/env python3
"""Writes docs/TEST-EVIDENCE.md and docs/TEST-EVIDENCE.json: per row, which levels of evidence exist and when (read-only report; no FEATURES.md column).

  python3 dist/autotest/evidence_report.py [--results DIR ...] [--out-md PATH] [--out-json PATH] [--features PATH]

Levels are never merged: unit (tests cited in the row), qemu, browser, machine-<name>, human. The Test number in FEATURES.md is derived from them by the
rules of docs/development/AUTOTEST.md; this report only shows the split. With no result folders only the unit level is shown. Output is deterministic.
"""
import argparse
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", ".."))
sys.path.insert(0, HERE)
import evidence  # noqa: E402
import results as R  # noqa: E402


def unit_count(tests_cell):
    return sum(1 for t in tests_cell.split("<br>") if t.strip().strip("`") and not t.strip().strip("`").startswith("script:") and t.strip() != "—")


def collect(features_text, result_dirs):
    rows, _ = evidence.parse_rows(features_text)
    per = {}
    for rid, (_i, c) in rows.items():
        per[rid] = {"test": int(c[5].split("/")[1]), "manual": c[6], "levels": {"unit": {"tests": unit_count(c[7])}}}
    for d in result_dirs:
        res, _skip = R.load_results(d)
        for r in res:
            row = per.get(r["row"])
            if row is None:
                continue
            lv = row["levels"].setdefault(r.get("level", r["target"]), {"last": "", "last_pass": "", "status": "", "commit": ""})
            if r["ran_at"] >= lv["last"]:
                lv.update({"last": r["ran_at"], "status": r["status"], "commit": r.get("commit", "")[:8]})
            if r["status"] == "PASS" and r["ran_at"] > lv["last_pass"]:
                lv["last_pass"] = r["ran_at"]
        hd = os.path.join(d, "human")
        if os.path.isdir(hd):
            for fn in sorted(os.listdir(hd)):
                try:
                    with open(os.path.join(hd, fn), encoding="utf-8") as fh:
                        h = json.load(fh)
                except (OSError, ValueError):
                    continue
                row = per.get(h.get("row"))
                if row is not None:
                    lv = row["levels"].setdefault("human", {"entries": []})
                    lv["entries"].append({"clause": h.get("clause"), "machine": h.get("machine"), "verdict": h.get("verdict"), "date": h.get("date")})
    for row in per.values():
        h = row["levels"].get("human")
        if h:
            h["entries"].sort(key=lambda e: (str(e["clause"]), str(e["machine"]), str(e["date"])))
    return per


def render_md(per):
    with_machine = {k: v for k, v in per.items() if len(v["levels"]) > 1}
    lines = ["# Test evidence by level", "",
             "Generated by `python3 dist/autotest/evidence_report.py`; read-only. Levels are never merged: `unit` (tests cited in the row), `qemu`, `browser`, `machine-<name>` (one level per paired machine) and `human`. "
             "FEATURES.md keeps its nine columns; its Test number is derived from these levels by the rules in [AUTOTEST.md](development/AUTOTEST.md). A row with no machine-made evidence is not listed.", "",
             "Rows with machine-made or human evidence: %d of %d." % (len(with_machine), len(per)), ""]
    if with_machine:
        lines += ["| Row | Test | Unit tests | Other levels (status, last PASS, image commit) |", "|---|---|---|---|"]
        for rid in sorted(with_machine):
            v = with_machine[rid]
            parts = []
            for name in sorted(k for k in v["levels"] if k != "unit"):
                lv = v["levels"][name]
                if name == "human":
                    parts.append("human: " + ", ".join("%s/%s %s %s" % (e["clause"], e["machine"], e["verdict"], e["date"]) for e in lv["entries"]))
                else:
                    parts.append("%s: %s, last PASS %s, %s" % (name, lv["status"], lv["last_pass"][:10] or "never", lv["commit"] or "?"))
            lines.append("| %s | %d | %d | %s |" % (rid, v["test"], v["levels"]["unit"]["tests"], "; ".join(parts)))
    else:
        lines.append("No machine-made evidence has been recorded yet.")
    return "\n".join(lines) + "\n"


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("--results", action="append", default=[])
    ap.add_argument("--features", default=os.path.join(ROOT, "FEATURES.md"))
    ap.add_argument("--out-md", default=os.path.join(ROOT, "docs", "TEST-EVIDENCE.md"))
    ap.add_argument("--out-json", default=os.path.join(ROOT, "docs", "TEST-EVIDENCE.json"))
    a = ap.parse_args(argv)
    with open(a.features, encoding="utf-8") as fh:
        per = collect(fh.read(), a.results)
    with open(a.out_md, "w", encoding="utf-8") as fh:
        fh.write(render_md(per))
    with open(a.out_json, "w", encoding="utf-8") as fh:
        json.dump({"levels": ["unit", "qemu", "browser", "machine-<name>", "human"], "rows": per}, fh, indent=1, sort_keys=True)
        fh.write("\n")
    print("wrote %s and %s (%d rows)" % (a.out_md, a.out_json, len(per)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
